INSERT INTO public.categories (slug, name, description, display_order) VALUES
  ('ai-and-jobs', 'AI & Jobs', 'How AI is changing work, careers, and skills in Nigeria.', 0),
  ('privacy', 'Privacy', 'Personal data, rights, and trust in an AI-driven economy.', 1),
  ('financial-security', 'Financial Security', 'Fintech, fraud, and keeping money safe as AI spreads.', 2),
