INSERT INTO public.blog_posts (slug, title, excerpt, content, cover_image_url, cover_image_alt, category_id, tags, is_free, reading_minutes, status, published_at)
SELECT 'will-ai-take-nigerian-jobs-or-create-new-ones', 'Will AI take Nigerian jobs, or create new ones?', 'The honest answer is both. What matters is which tasks change first, who gets to adapt, and what we do in the next few years.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every few weeks a new headline announces that AI is coming for our jobs. Most of those headlines are written with other labour markets in mind. Nigeria''s economy looks different, and so will the way AI reshapes it."}]},{"type":"paragraph","content":[{"type":"text","text":"The useful question is not \"will AI replace people?\" but \"which tasks will change first, and who will be ready when they do?\""}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Tasks change before jobs do"}]},{"type":"paragraph","content":[{"type":"text","text":"AI tools are good at drafting, summarising, classifying, and answering routine questions. That means the first changes show up inside jobs: the customer support agent who now handles more complex cases, the analyst who spends less time cleaning spreadsheets, the marketer who can test ten versions of an ad instead of two."}]},{"type":"paragraph","content":[{"type":"text","text":"Roles built almost entirely from repetitive, screen-based tasks are the most exposed. Roles that depend on judgement, trust, relationships, and local context are much harder to automate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Where new work appears"}]},{"type":"paragraph","content":[{"type":"text","text":"New tools create new work around them. Someone has to adapt AI products to Nigerian languages, accents, and business realities. Someone has to label data, evaluate outputs, build integrations, train teams, and explain risks to customers and regulators."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Builders","marks":[{"type":"bold"}]},{"type":"text","text":" who can ship AI features into products Nigerians already use"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Translators","marks":[{"type":"bold"}]},{"type":"text","text":" between technology and industries like agriculture, logistics, health, and finance"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trust roles","marks":[{"type":"bold"}]},{"type":"text","text":" covering data protection, security, quality, and responsible use"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What to do now"}]},{"type":"paragraph","content":[{"type":"text","text":"If you are early in your career, learn to use AI tools well and pair that with a domain you understand deeply. If you lead a team, start small experiments, measure what actually improves, and invest in reskilling before you restructure."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"The people most at risk are not those whose jobs AI can touch. They are the ones who never get the chance to adapt."}]}]},{"type":"paragraph","content":[{"type":"text","text":"At C8 Tech Summit 2026 we will put these questions to builders, employers, and emerging professionals, and ask what a fair transition looks like for Nigeria."}]}]}'::jsonb, '/images/blog/ai-jobs.webp', 'Young professionals collaborating around laptops at a workshop table',
  (SELECT id FROM public.categories WHERE slug = 'ai-and-jobs'), ARRAY['AI', 'jobs', 'skills']::text[], false, 2, 'published', '2026-09-16T09:00:00+01:00'
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.blog_posts (slug, title, excerpt, content, cover_image_url, cover_image_alt, category_id, tags, is_free, reading_minutes, status, published_at)
SELECT 'what-your-data-is-worth-in-an-ai-economy', 'What your data is worth in an AI economy', 'AI runs on personal data. Here is what that means for Nigerians, the rights you already have, and what builders should get right.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every app you sign up for asks for something: your phone number, your BVN, your location, your contacts. AI systems make that information more valuable, because patterns in data are exactly what they learn from."}]},{"type":"paragraph","content":[{"type":"text","text":"That raises a simple question with complicated answers: who benefits from your data, and who protects it?"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Data is the raw material"}]},{"type":"paragraph","content":[{"type":"text","text":"Recommendation engines, credit scoring models, fraud detection, and chatbots all improve with more data. That creates a strong incentive to collect as much as possible and keep it for as long as possible."}]},{"type":"paragraph","content":[{"type":"text","text":"For users, the risk is not only a data breach. It is also being profiled, priced, or refused a service by a system you cannot see or question."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"You already have rights"}]},{"type":"paragraph","content":[{"type":"text","text":"The Nigeria Data Protection Act 2023 gives people rights over their personal data, including the right to be informed about how it is used, to access it, to correct it, and in many cases to have it deleted. Organisations need a lawful basis to process personal data and must keep it secure."}]},{"type":"paragraph","content":[{"type":"text","text":"Rights only matter if people know about them and companies take them seriously."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What builders should get right"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Collect only what the product genuinely needs"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain, in plain language, what data is used for, including AI training"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Make it easy to access, correct, and delete data"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Treat security as a product feature, not an afterthought"}]}]}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Trust is a competitive advantage. The products that win in Nigeria''s AI era will be the ones people feel safe using."}]}]},{"type":"paragraph","content":[{"type":"text","text":"Our 2026 summit will bring builders, privacy professionals, and everyday users together to talk about what responsible data use should look like in Nigeria."}]}]}'::jsonb, '/images/blog/privacy.webp', 'Professionals reviewing information on tablets in a bright office',
  (SELECT id FROM public.categories WHERE slug = 'privacy'), ARRAY['privacy', 'data protection', 'NDPA']::text[], false, 1, 'published', '2026-09-23T09:00:00+01:00'
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.blog_posts (slug, title, excerpt, content, cover_image_url, cover_image_alt, category_id, tags, is_free, reading_minutes, status, published_at)
SELECT 'ai-powered-fraud-and-how-to-stay-a-step-ahead', 'AI-powered fraud and how to stay a step ahead', 'Scammers are using AI too: cloned voices, convincing messages, fake documents. Here is how individuals and fintech teams can respond.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Nigerians have become experts at spotting a badly written scam message. AI is removing those warning signs. Messages are now fluent, personalised, and sent at scale. Voices can be cloned from a short clip. Documents can be faked in minutes."}]},{"type":"paragraph","content":[{"type":"text","text":"The good news is that AI is also one of the best tools we have for fighting back."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How the threat is changing"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Better impersonation:","marks":[{"type":"bold"}]},{"type":"text","text":" messages and calls that sound exactly like a bank, an employer, or a family member"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Scale:","marks":[{"type":"bold"}]},{"type":"text","text":" thousands of tailored attempts instead of one generic broadcast"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Synthetic identities:","marks":[{"type":"bold"}]},{"type":"text","text":" fake profiles and documents used to open accounts or take loans"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What individuals can do"}]},{"type":"paragraph","content":[{"type":"text","text":"Slow down whenever a message creates urgency. Verify requests for money through a second channel you already trust, such as calling the person back on a number you know. Agree on a simple code word with family for emergencies. Never share one-time passwords, whoever asks."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"What fintech teams can do"}]},{"type":"paragraph","content":[{"type":"text","text":"Fraud prevention has to be layered. Behavioural signals, device checks, transaction monitoring, and fast human review all matter. AI models can flag unusual patterns in real time, but they need good data, regular testing, and clear routes for customers to report and recover."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Security that frustrates honest customers pushes them away. The goal is protection that feels invisible until it is needed."}]}]},{"type":"paragraph","content":[{"type":"text","text":"At C8 Tech Summit 2026 we will hear from people building payments and security products about what is working, and what everyone else can learn from them."}]}]}'::jsonb, '/images/blog/fraud.webp', 'A team discussing data on a large digital screen in a modern office',
  (SELECT id FROM public.categories WHERE slug = 'financial-security'), ARRAY['fraud', 'fintech', 'security']::text[], false, 1, 'published', '2026-09-30T09:00:00+01:00'
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.blog_posts (slug, title, excerpt, content, cover_image_url, cover_image_alt, category_id, tags, is_free, reading_minutes, status, published_at)
SELECT 'why-c8-is-giving-emerging-voices-the-stage', 'Why C8 is giving emerging voices the stage', 'Most tech events spotlight people who have already made it. We think great ideas also come from people who are just getting started.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Nigeria''s tech ecosystem is full of talented founders, builders, researchers, and young professionals doing great work. But they do not always have the right platforms to meet, share ideas, learn from each other, or find opportunities."}]},{"type":"paragraph","content":[{"type":"text","text":"Most tech events focus on people who have already made it: successful founders, executives, and well-known leaders. Their experience matters. But great ideas don''t only come from people who are already successful."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"A seat at the table"}]},{"type":"paragraph","content":[{"type":"text","text":"C8 Tech Summit exists to bring different parts of the ecosystem together, emerging and established, and give emerging voices real space to share their ideas and help shape where the industry goes next."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Have important conversations"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Share knowledge"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Meet and build relationships"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Discover opportunities"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Collaborate on ideas"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"This year''s conversation"}]},{"type":"paragraph","content":[{"type":"text","text":"Our 2026 theme is "},{"type":"text","text":"Navigating Nigeria''s AI Revolution: Jobs, Privacy, & Financial Security","marks":[{"type":"italic"}]},{"type":"text","text":". AI is a global conversation, but much of it is shaped by experiences outside Nigeria. We want to bring it home: what AI actually means for our jobs, our data, our businesses, and our everyday lives."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Join us"}]},{"type":"paragraph","content":[{"type":"text","text":"The summit is live online on 15 October 2026 at 4:00 PM WAT. Register on this site and we will send your joining link before the event. Bring your questions, and your ideas."}]}]}'::jsonb, '/images/blog/community.webp', 'Attendees networking in a lively event space',
  (SELECT id FROM public.categories WHERE slug = 'community'), ARRAY['community', 'C8 Tech Summit']::text[], true, 1, 'published', '2026-10-03T09:00:00+01:00'
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.blog_posts (slug, title, excerpt, content, cover_image_url, cover_image_alt, category_id, tags, is_free, reading_minutes, status, published_at)
SELECT 'five-ai-skills-every-nigerian-professional-can-learn-this-year', 'Five AI skills every Nigerian professional can learn this year', 'You don''t need to become a machine learning engineer. These practical skills will make you more effective in almost any role.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Learning about AI can feel overwhelming. The good news is that the most valuable skills for most professionals are practical, and you can start building them this week."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. Asking good questions"}]},{"type":"paragraph","content":[{"type":"text","text":"Getting useful output from AI tools depends on clear instructions: context, constraints, examples, and the format you want. This is really a communication skill, and it improves with practice."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Checking the work"}]},{"type":"paragraph","content":[{"type":"text","text":"AI tools can be confidently wrong. Knowing how to verify facts, test outputs, and spot gaps is what separates people who use AI well from people who are misled by it."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. Working with data"}]},{"type":"paragraph","content":[{"type":"text","text":"You do not need to be a data scientist, but understanding where data comes from, how it can be biased, and how to read a simple chart will help you make better decisions with AI tools."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Automating the boring parts"}]},{"type":"paragraph","content":[{"type":"text","text":"Many everyday tasks, such as drafting emails, summarising meetings, and organising information, can be partly automated. Learning to spot those opportunities frees time for higher-value work."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"5. Thinking about risk"}]},{"type":"paragraph","content":[{"type":"text","text":"Responsible use means knowing what not to paste into a tool, when a decision needs a human, and how to protect customers'' privacy. Employers increasingly value people who can use AI safely."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"Start with one tool, one task, and one week. Small experiments compound."}]}]},{"type":"paragraph","content":[{"type":"text","text":"We will be talking about skills, careers, and the future of work at C8 Tech Summit 2026."}]}]}'::jsonb, '/images/blog/skills.webp', 'Colleagues at a workshop discussing ideas over laptops and notes',
  (SELECT id FROM public.categories WHERE slug = 'ai-and-jobs'), ARRAY['skills', 'careers', 'AI']::text[], false, 1, 'published', '2026-10-06T09:00:00+01:00'
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.blog_posts (slug, title, excerpt, content, cover_image_url, cover_image_alt, category_id, tags, is_free, reading_minutes, status, published_at)
